#include <iostream>
struct D { int v; D* prev; D* next; };
int main() {
    D b{2, nullptr, nullptr}, a{1, nullptr, &b};
    b.prev = &a;
    std::cout << a.next->v << " " << b.prev->v << "\n";
    return 0;
}

#include <iostream>
struct N { int v; N* next; };
int main() {
    N c{3, nullptr}, b{2, &c}, a{1, &b};
    c.next = &a;
    N* p = &a;
    std::cout << p->v << p->next->v << p->next->next->v << "\n";
    return 0;
}

#include <iostream>
struct D { int v; D* prev; D* next; };
int main() {
    D c{3, nullptr, nullptr}, b{2, nullptr, &c}, a{1, nullptr, &b};
    c.prev = &b;
    b.prev = &a;
    for (D* p = &c; p; p = p->prev) std::cout << p->v;
    std::cout << "\n";
    return 0;
}

#include <iostream>
struct N { int v; N* next; };
int main() {
    N c{3, nullptr}, b{2, &c}, a{1, &b};
    c.next = &a;
    N* p = &b;
    p->next = p->next->next;
    std::cout << p->next->v << "\n";
    return 0;
}

#include <iostream>
struct D { int v; D* prev; D* next; };
int main() {
    D c{3, nullptr, nullptr}, b{2, nullptr, &c}, a{1, nullptr, &b};
    c.prev = &b;
    b.prev = &a;
    b.prev->next = b.next;
    b.next->prev = b.prev;
    std::cout << a.next->v << c.prev->v << "\n";
    return 0;
}

#include <iostream>
struct N { int v; N* next; };
int main() {
    N c{3, nullptr}, b{2, &c}, a{1, &b};
    c.next = &a;
    int count = 1;
    N* p = a.next;
    while (p != &a) { count++; p = p->next; }
    std::cout << count << "\n";
    return 0;
}

#include <iostream>
struct N { int v; N* next; };
int main() {
    N x{9, nullptr}, c{3, nullptr}, b{2, &c}, a{1, &b};
    c.next = &a;
    N* p = &a;
    while (p->next != &a) p = p->next;
    p->next = &x;
    x.next = &a;
    std::cout << x.next->v << p->next->v << "\n";
    return 0;
}
